tape( 'the function returns NaN for negative numbers', function test( t ) {
	var v;
	var x;
	var i;

	for ( i = 0; i < 1000; i++ ) {
		x = -( randu() * 100.0 ) - EPS;
		v = k1( x );
		t.ok( isnan( v ), 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns +Infinity if provided 0.0', function test( t ) {
	var v = k1( 0.0 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns NaN if provided NaN', function test( t ) {
	var v = k1( NaN );
	t.ok( isnan( v ), 'returns expected value' );
	t.end();
});

tape( 'the function returns 0.0 if provided +Infinity', function test( t ) {
	var v = k1( PINF );
	t.strictEqual( v, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns NaN if provided -Infinity', function test( t ) {
	var v = k1( NINF );
	t.ok( isnan( v ), 'returns expected value' );
	t.end();
});
